class Solution:
    def gcdSort(self, nums: List[int]) -> bool:
        n = len(nums)
        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                if gcd(nums[i], nums[j]) > 1:
                    adj[i].append(j)
                    adj[j].append(i)
        comp = [-1] * n
        for s in range(n):
            if comp[s] != -1:
                continue
            q = deque([s])
            comp[s] = s
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if comp[v] == -1:
                        comp[v] = s
                        q.append(v)
        target = sorted(nums)
        groups = defaultdict(list)
        for i in range(n):
            groups[comp[i]].append(nums[i])
        for g in groups.values():
            g.sort()
        pos = Counter()
        for i in range(n):
            c = comp[i]
            if groups[c][pos[c]] != target[i]:
                return False
            pos[c] += 1
        return True

