class Solution {
public:
    bool gcdSort(vector<int>& nums) {
        int n = nums.size();
        vector<vector<int>> adj(n);
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (__gcd(nums[i], nums[j]) > 1) {
                    adj[i].push_back(j);
                    adj[j].push_back(i);
                }
        vector<int> comp(n, -1);
        for (int s = 0; s < n; s++) {
            if (comp[s] != -1) continue;
            queue<int> q;
            q.push(s);
            comp[s] = s;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : adj[u])
                    if (comp[v] == -1) { comp[v] = s; q.push(v); }
            }
        }
        vector<int> target = nums;
        sort(target.begin(), target.end());
        map<int, vector<int>> groups;
        for (int i = 0; i < n; i++) groups[comp[i]].push_back(nums[i]);
        map<int, int> pos;
        for (auto& kv : groups) sort(kv.second.begin(), kv.second.end());
        for (int i = 0; i < n; i++) {
            int c = comp[i];
            if (groups[c][pos[c]] != target[i]) return false;
            pos[c]++;
        }
        return true;
    }
};

