class Solution {
    public boolean gcdSort(int[] nums) {
        int n = nums.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (gcd(nums[i], nums[j]) > 1) {
                    adj.get(i).add(j);
                    adj.get(j).add(i);
                }
        int[] comp = new int[n];
        Arrays.fill(comp, -1);
        for (int s = 0; s < n; s++) {
            if (comp[s] != -1) continue;
            Deque<Integer> q = new ArrayDeque<>();
            q.offer(s);
            comp[s] = s;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : adj.get(u))
                    if (comp[v] == -1) { comp[v] = s; q.offer(v); }
            }
        }
        int[] target = nums.clone();
        Arrays.sort(target);
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < n; i++)
            groups.computeIfAbsent(comp[i], k -> new ArrayList<>()).add(nums[i]);
        Map<Integer, Integer> pos = new HashMap<>();
        for (List<Integer> g : groups.values()) Collections.sort(g);
        for (int i = 0; i < n; i++) {
            int c = comp[i];
            int p = pos.getOrDefault(c, 0);
            if (groups.get(c).get(p) != target[i]) return false;
            pos.put(c, p + 1);
        }
        return true;
    }

    private int gcd(int a, int b) {
        while (b != 0) { int t = a % b; a = b; b = t; }
        return a;
    }
}

