var gcdSort = function(nums) {
    const n = nums.length;
    const gcd = (a, b) => { while (b) { const t = a % b; a = b; b = t; } return a; };
    const adj = Array.from({ length: n }, () => []);
    for (let i = 0; i < n; i++)
        for (let j = i + 1; j < n; j++)
            if (gcd(nums[i], nums[j]) > 1) {
                adj[i].push(j);
                adj[j].push(i);
            }
    const comp = new Array(n).fill(-1);
    for (let s = 0; s < n; s++) {
        if (comp[s] !== -1) continue;
        const q = [s];
        comp[s] = s;
        for (let h = 0; h < q.length; h++) {
            const u = q[h];
            for (const v of adj[u])
                if (comp[v] === -1) { comp[v] = s; q.push(v); }
        }
    }
    const target = [...nums].sort((x, y) => x - y);
    const groups = new Map();
    for (let i = 0; i < n; i++) {
        if (!groups.has(comp[i])) groups.set(comp[i], []);
        groups.get(comp[i]).push(nums[i]);
    }
    for (const g of groups.values()) g.sort((x, y) => x - y);
    const pos = new Map();
    for (let i = 0; i < n; i++) {
        const c = comp[i];
        const p = pos.get(c) || 0;
        if (groups.get(c)[p] !== target[i]) return false;
        pos.set(c, p + 1);
    }
    return true;
};

