class Solution:
    def gcdSort(self, nums: List[int]) -> bool:
        mx = max(nums)
        spf = list(range(mx + 1))
        i = 2
        while i * i <= mx:
            if spf[i] == i:
                for j in range(i * i, mx + 1, i):
                    if spf[j] == j:
                        spf[j] = i
            i += 1
        parent = list(range(mx + 1))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for x in nums:
            y = x
            while y > 1:
                p = spf[y]
                ra, rb = find(x), find(p)
                if ra != rb:
                    parent[ra] = rb
                while y % p == 0:
                    y //= p
        return all(find(x) == find(y) for x, y in zip(nums, sorted(nums)))

