var gcdSort = function(nums) {
    let mx = 0;
    for (const x of nums) if (x > mx) mx = x;
    const spf = new Int32Array(mx + 1);
    for (let i = 0; i <= mx; i++) spf[i] = i;
    for (let i = 2; i * i <= mx; i++)
        if (spf[i] === i)
            for (let j = i * i; j <= mx; j += i)
                if (spf[j] === j) spf[j] = i;
    const par = new Int32Array(mx + 1);
    for (let i = 0; i <= mx; i++) par[i] = i;
    const find = (x) => {
        while (par[x] !== x) {
            par[x] = par[par[x]];
            x = par[x];
        }
        return x;
    };
    for (const x of nums) {
        let y = x;
        while (y > 1) {
            const p = spf[y];
            const ra = find(x), rb = find(p);
            if (ra !== rb) par[ra] = rb;
            while (y % p === 0) y /= p;
        }
